WFJ.Data.add("gossip", {
  ["110e558557122d71"] = { "%s ride.", "." },
  ["110f1054b8426e4c"] = { "Finalmente è finita....", "." },
  ["11122d4a8048ba48"] = { "Forza, Dadanga! Marcia, ragazza, marcia!", "." },
  ["1117e0c58c3c6538"] = { "Accedi agli schemi segreti di ingegneria goblin!", "." },
  ["111af97ca580592a"] = { "Molto interessante!", "." },
  ["111b0c477c9bf5c0"] = { "Va bene. È fatto!", "." },
  ["111e9a3233efea71"] = { "Non vedo l'ora di scatenarmi, Vipore! Dammi un segnalatore.", "." },
  ["111f48b5f367594c"] = { "A volte mi chiedo se Surena non fosse una succube sotto mentite spoglie, mandata a deformare e distorcere la mia mente... Ah! Credo di darle troppo credito.", "." },
  ["11291b16b35a7db0"] = { "La battaglia finale per Kalimdor è alle porte. Il comandante supremo della ⟦Might of Kalimdor=Forza di Kalimdor⟧ ordina alle sue truppe di marciare su ⟦Ahn'Qiraj=Ahn'qiraj⟧ e distruggere tutto ciò che trovano sul loro cammino.", "." },
  ["112adb4159d347ea"] = { "Che la tua morte serva da esempio!", "." },
  ["112fdb44b0f2c310"] = { "{name}, sono qui per scoprire quanto siano diffusi gli effetti del ⟦Fel Moss=Vilmuschio⟧ in tutta ⟦Darkshore=Rivafosca⟧. La corruzione di Teldrassil e delle terre che ci circondano preoccupa molto i druidi del Circolo Cenariano e tutti gli elfi della notte.\n\nIl mio obiettivo è scoprire perché sia successo e porvi fine.", "." },
  ["113391a9a41af576"] = { "Paladini nel ⟦War Quarter=Quartiere della Guerra⟧, sull'anello esterno. Li trovi nell'edificio principale.", "." },
  ["1135eecfa03eea78"] = { "Pront<o/a> per un'altra lezione? D'accordo, allora. Prima di tutto, rilassati. Bisogna restare sciolti per mescolare una pozione come si deve.", "." },
  ["1136a0ec6faf3f85"] = { "Tra un'ora sono di servizio, ma fino ad allora... cin cin!", "." },
  ["11383c07c9e04207"] = { "Salute, sono Baros Alexston, architetto cittadino di ⟦Stormwind=Roccavento⟧.", "." },
  ["1160118dd366a083"] = { "Non hai lo stomaco per il volo in grifone, eh? Be', per tua fortuna abbiamo un'alternativa che ti permette di tenere i piedi per terra... più o meno. È lo spostatore di persone gnomesco, il ⟦Deeprun Tram=Tram degli Abissi⟧. Comodamente situato in fondo al Distretto dei Nani.", "." },
  ["116a9aeedca84590"] = { "Si dice che Vance Undergloom abbia preso una stanza fissa al piano di sopra della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, all'estremità sud-orientale della città. Credo sia appena oltre la sala di lettura.", "." },
  ["1185c09dddd658f0"] = { "La terra, l'acqua e il cielo sono una cosa sola. Sono i tuoi occhi a ingannarti con questa separazione. La Madre Terra è tutte queste cose e molto di più.", "." },
  ["1186c284f4ee0bf8"] = { "Ehi, di' al tuo amico Tongus che se non salda il suo conto qui, mi farò vivo con il vecchio Steelhead!", "." },
  ["118de952e0841ddd"] = { "Killian Hagey insegna scuoiatura nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧, sull'anello interno.", "." },
  ["118f32597523b7e5"] = { "E tu che ne dici?", "." },
  ["1195791c31266679"] = { "%s comincia un incantesimo di evocazione...", "." },
  ["119a2e5012b8a20c"] = { "Dove si era interrotto?", "." },
  ["119e0cf7b7d7dc72"] = { "Ho bisogno di addestramento, Zamja.", "." },
  ["119e6bd3e0aa8b02"] = { "Rilevate forme di vita sconosciute....analisi in corso...", "." },
  ["11a112eefd03c467"] = { "Credevi davvero di avere una possibilità?", "." },
  ["11b4817fcc8e4a35"] = { "%s scoppia in una risata folle.", "." },
  ["11b99a823fc237f9"] = { "⟦Icebane Bracers=Bracciali della Rovina dei Ghiacci⟧.", "." },
  ["11bbdc90f74a228d"] = { "<Un/Una> semplice {class} mi sfida? Preparati per l'aldilà!", "." },
  ["11befbc7d94e78b7"] = { "Guarda il cielo, {class}. Gli Stormi dei Draghi non si vedevano da queste parti da mille anni! Quei Qiraji stanno tramando qualcosa, me lo sento!", "." },
  ["11bfa7da06fda8d5"] = { "Sia il capitano dell'⟦Horde=Orda⟧ sia quello dell'⟦Alliance=Alleanza⟧ sono scesi in campo. Il nostro capitano Galvangar guida i Lupi Bianchi dal ⟦Iceblood Garrison=Presidio di Brinarossa⟧, e la sua rivale, il capitano Balinda Stonehearth, si nasconde nel suo ⟦Stonehearth Outpost=Avamposto di Cordipietra⟧.\n\nLa battaglia è cominciata!", "." },
  ["11cae6efdbd5f332"] = { "Che peccato, e scommetto che avevi affilato il coltello apposta pensando di scuoiare qualche pelle per me. Ahimè, abbiamo già raccolto tutto il Cuoio Duro necessario, {class}. Renditi utile, comunque, e chiedi agli altri qui se hanno altri incarichi di raccolta da affidarti.", "." },
  ["11d1a8b89718d066"] = { "Quando arriverà la ⟦Darkmoon Faire=Fiera di Lunacupa⟧, dove si troverà?", "." },
  ["11d5d27703a591ef"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di insegnarti.\n\nNon fa mai male riaffermare il proprio posto in quello che mi piace chiamare il Grande Equilibrio. Come custodi di questo equilibrio, dobbiamo sforzarci di mantenere sempre la mente lucida e il cuore saldo. L'addestramento ci aiuta in questo.", "." },
  ["11de0c91a16745fe"] = { "Cosa abbiamo qui? {name} <il/la> {class}? All'attacco!", "." },
  ["11de61f909305612"] = { "Sei <venuto/venuta> a salvare questo mondo? A purificarlo?", "." },
  ["11e1703b3eae47b7"] = { "ASSAGGIATE LE FIAMME DI SULFURON!", "." },
  ["11eb9742b56f775c"] = { "Ohoh! Accoglierei volentieri la sfida del vecchio pancia molle!", "." },
  ["11f56b4ed6e17393"] = { "Salute. Insegno ai maghi, e tu sei <un/una> <mago/maga>.", "." },
})
